<script setup>
import axios from 'axios';
import { computed, onMounted, reactive, ref } from 'vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import PaginationControls from '../../components/PaginationControls.vue';
import { useConfirmDialog } from '../../composables/useConfirmDialog';
import { useUnsavedForm } from '../../composables/useUnsavedForm';

import { formatRupiah } from '../../utils/money';
const props = defineProps({ workspaceId: { type: [String, Number], required: true }, timezone: { type: String, default: 'Asia/Jakarta' } });
const { open: confirmOpen, options: confirmOptions, confirm: askConfirm, finish: finishConfirm } = useConfirmDialog();
const events = ref([]); const pagination = ref(null); const currentPage = ref(1); const nextEventData = ref(null); const loading = ref(true); const error = ref(''); const showForm = ref(false); const editId = ref(null); const saving = ref(false);
const eventForm = reactive(blankEvent()); const formError = ref('');
const savedEventForm = ref('');
const eventFormDirty = computed(() => JSON.stringify(eventForm) !== savedEventForm.value);
const eventFormGuard = useUnsavedForm({ isOpen: showForm, isDirty: eventFormDirty, confirm: askConfirm, onDiscard: () => { showForm.value = false; }, title: 'Perubahan acara belum disimpan' });
const nextEvent = computed(() => nextEventData.value ?? events.value.find((event) => event.event_date && event.event_date >= new Date().toLocaleDateString('en-CA', { timeZone: props.timezone })) ?? null);
function blankEvent() { return { title: '', event_type: 'ceremony', event_date: '', start_time: '', end_time: '', venue_name: '', address: '', notes: '' }; }
function eventType(type) { return { engagement: 'Lamaran', ceremony: 'Akad / Pemberkatan', reception: 'Resepsi', family: 'Acara keluarga', other: 'Acara lainnya' }[type] ?? type; }
function dateLabel(value) { return value ? new Date(`${value}T12:00:00Z`).toLocaleDateString('id-ID', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : 'Tanggal belum ditentukan'; }
async function load(page = currentPage.value) {
    loading.value = true;
    error.value = '';
    try {
        const { data } = await axios.get(`/api/workspaces/${props.workspaceId}/events`, { params: { page, per_page: 20 } });
        if (page > data.pagination.last_page && data.pagination.last_page > 0) return await load(data.pagination.last_page);
        events.value = data.events;
        pagination.value = data.pagination;
        currentPage.value = data.pagination.current_page;
        nextEventData.value = data.next_event;
    } catch {
        error.value = 'Acara belum berhasil dimuat. Coba lagi.';
    } finally {
        loading.value = false;
    }
}
function createEvent() { editId.value = null; Object.assign(eventForm, blankEvent()); savedEventForm.value = JSON.stringify(eventForm); formError.value = ''; showForm.value = true; }
function editEvent(event) { editId.value = event.id; Object.assign(eventForm, { ...blankEvent(), ...event, start_time: event.start_time?.slice(0,5) ?? '', end_time: event.end_time?.slice(0,5) ?? '' }); savedEventForm.value = JSON.stringify(eventForm); formError.value = ''; showForm.value = true; }
async function saveEvent() { saving.value = true; formError.value = ''; try { const body = { ...eventForm, event_date: eventForm.event_date || null, start_time: eventForm.start_time || null, end_time: eventForm.end_time || null }; if (editId.value) await axios.patch(`/api/workspaces/${props.workspaceId}/events/${editId.value}`, body); else await axios.post(`/api/workspaces/${props.workspaceId}/events`, body); showForm.value = false; await load(editId.value ? currentPage.value : 1); } catch (e) { formError.value = e.response?.data?.message ?? 'Acara belum berhasil disimpan.'; } finally { saving.value = false; } }
onMounted(load);
</script>

<template>
    <section class="events-page" aria-labelledby="events-title">
        <header class="events-head"><div><p class="eyebrow"><span class="eyebrow__dot"></span> HARI-H DAN RANGKAIANNYA</p><h1 id="events-title">Acara & Jadwal</h1><p>Atur waktu, lokasi, dan agenda setiap momen penting.</p></div><button class="button button--primary" @click="createEvent"><FaIcon :icon="['fas','plus']" /> Tambah acara</button></header>
        <div v-if="loading" class="home-skeleton"><div class="skeleton-line skeleton-line--title"></div><div class="skeleton-block"></div></div>
        <div v-else-if="error && !events.length" class="page-error" role="alert"><p>{{ error }}</p><button class="button button--quiet" @click="load">Coba lagi</button></div>
        <template v-else>
            <section class="event-next" aria-label="Acara berikutnya"><div><span>ACARA BERIKUTNYA</span><template v-if="nextEvent"><h2>{{ nextEvent.title }}</h2><p>{{ dateLabel(nextEvent.event_date) }}<span v-if="nextEvent.start_time"> · {{ nextEvent.start_time.slice(0,5) }}</span></p></template><template v-else><h2>Hari istimewa dimulai dari rencana yang jelas.</h2><p>Tambahkan acara pertama kalian untuk mengatur tanggal dan rangkaiannya.</p></template></div><div class="event-next__date" v-if="nextEvent"><strong>{{ nextEvent.event_date?.slice(8,10) }}</strong><span>{{ new Date(`${nextEvent.event_date}T12:00:00Z`).toLocaleDateString('id-ID',{month:'short',timeZone:'UTC'}) }}</span></div></section>
            <div v-if="error" class="guest-error" role="alert">{{ error }}</div>
            <div v-if="!events.length" class="event-empty"><span><FaIcon :icon="['fas','calendar-days']" /></span><h2>Belum ada acara</h2><p>Tambahkan akad, resepsi, atau acara keluarga agar jadwal kalian terorganisir.</p><button class="button button--primary" @click="createEvent">Buat acara pertama</button></div>
            <TransitionGroup v-else name="list" tag="section" class="event-grid" aria-label="Daftar acara"><article v-for="event in events" :key="event.id" class="event-card"><div class="event-card__top"><span>{{ eventType(event.event_type) }}</span><RouterLink class="icon-button" :aria-label="`Ubah ${event.title}`" :to="`/app/events/${event.id}/edit`"><FaIcon :icon="['fas','pen']" /></RouterLink></div><RouterLink class="event-card__title" :to="`/app/events/${event.id}`">{{ event.title }}</RouterLink><p class="event-card__date"><FaIcon :icon="['fas','calendar-days']" /> {{ dateLabel(event.event_date) }}</p><p v-if="event.venue_name" class="event-card__venue"><FaIcon :icon="['fas','location-dot']" /> {{ event.venue_name }}</p><p class="event-card__needs"><FaIcon :icon="['fas','leaf']" /> <template v-if="event.needs_summary?.total">{{ event.needs_summary.total }} kebutuhan · estimasi {{ formatRupiah(event.needs_summary.estimated) }} · aktual {{ formatRupiah(event.needs_summary.actual) }}</template><template v-else>Belum ada kebutuhan</template></p><div class="event-card__footer"><span>{{ event.agenda_items_count }} agenda</span><RouterLink :to="`/app/events/${event.id}`">Buka detail <FaIcon :icon="['fas','arrow-right']" /></RouterLink></div></article></TransitionGroup>
            <PaginationControls v-if="events.length" :pagination="pagination" @change="load" />
        </template>
        <Transition name="overlay" appear>
        <div v-if="showForm" class="sheet-backdrop" @click.self="eventFormGuard.requestClose()"><aside class="guest-sheet" role="dialog" aria-modal="true" aria-labelledby="event-form-title"><header><div><p class="eyebrow">ACARA KALIAN</p><h2 id="event-form-title">{{ editId ? 'Ubah acara' : 'Tambah acara' }}</h2></div><button class="icon-button" aria-label="Tutup" @click="eventFormGuard.requestClose()"><FaIcon :icon="['fas','xmark']" /></button></header><form @submit.prevent="saveEvent"><label>Nama acara<input v-model.trim="eventForm.title" required maxlength="160" placeholder="Contoh: Akad nikah" /></label><div class="guest-form-row"><label>Jenis acara<MotionSelect v-model="eventForm.event_type"><option value="engagement">Lamaran</option><option value="ceremony">Akad / Pemberkatan</option><option value="reception">Resepsi</option><option value="family">Acara keluarga</option><option value="other">Lainnya</option></MotionSelect></label><label>Tanggal<input v-model="eventForm.event_date" type="date" /></label></div><div class="guest-form-row"><label>Mulai<input v-model="eventForm.start_time" type="time" /></label><label>Selesai<input v-model="eventForm.end_time" type="time" /></label></div><label>Lokasi<input v-model.trim="eventForm.venue_name" maxlength="160" placeholder="Nama venue" /></label><label>Alamat<textarea v-model.trim="eventForm.address" rows="2" placeholder="Alamat lengkap" /></label><label>Catatan<textarea v-model.trim="eventForm.notes" rows="3" /></label><p v-if="formError" class="guest-error">{{ formError }}</p><footer><button class="button button--quiet" type="button" @click="eventFormGuard.requestClose()">Batal</button><button class="button button--primary" :disabled="saving">{{ saving ? 'Menyimpan…' : 'Simpan acara' }}</button></footer></form></aside></div>
        </Transition>
        <ConfirmDialog :open="confirmOpen" :title="confirmOptions.title" :message="confirmOptions.message" :confirm-label="confirmOptions.confirmLabel" @cancel="finishConfirm(false)" @confirm="finishConfirm(true)" />
    </section>
</template>

<style scoped>
.events-page{max-width:1180px;margin:auto;padding:38px clamp(20px,4vw,56px) 70px;color:#30362e}.events-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin:12px 0 28px}.events-head h1{font:500 clamp(42px,5vw,58px)/1 var(--font-display);margin:14px 0 9px}.events-head p:last-child{color:#5f675c;font-size:14px;margin:0}.event-next{background:#e9ede5;border:1px solid #dfe4d9;border-radius:18px;padding:25px 28px;display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.event-next>div:first-child>span{font-size:10px;letter-spacing:1.2px;color:#687560;font-weight:700}.event-next h2{font:500 28px var(--font-display);margin:8px 0 5px}.event-next p{font-size:12px;color:#5f675c;margin:0}.event-next__date{width:74px;height:74px;border-radius:14px;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#536a54}.event-next__date strong{font:500 31px var(--font-display)}.event-next__date span{font-size:11px;text-transform:uppercase}.event-empty{text-align:center;padding:48px 20px;background:#fff;border:1px solid #e6e6df;border-radius:16px}.event-empty>span{width:50px;height:50px;border-radius:50%;background:#eff2eb;color:#536a54;display:grid;place-items:center;margin:auto auto 12px}.event-empty h2{font:500 29px var(--font-display);margin:0 0 7px}.event-empty p{font-size:13px;color:#5f675c;margin:0 auto 20px;max-width:440px}.event-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.event-card{background:#fff;border:1px solid #e6e6df;border-radius:15px;padding:19px 21px}.event-card__top{display:flex;justify-content:space-between;align-items:center}.event-card__top>span{font-size:10px;letter-spacing:.8px;text-transform:uppercase;color:#65745e;font-weight:700}.event-card__title{display:block;border:0;background:none;text-align:left;padding:0;color:inherit;font:500 27px var(--font-display);cursor:pointer;margin:3px 0 13px}.event-card__date,.event-card__venue{font-size:12px;color:#72796f;display:flex;gap:8px;align-items:center}.event-card__needs{display:flex;align-items:flex-start;gap:7px;font-size:10px;line-height:1.5;color:#687260;background:#f4f6f0;border-radius:8px;padding:8px 10px;margin:11px 0 0}.event-card__needs svg{flex:0 0 auto;margin-top:1px;color:#536a54}.event-card__footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #eeeee8;margin-top:17px;padding-top:12px;font-size:11px;color:#7b8177}.event-card__footer button,.event-card__footer a{border:0;background:none;color:#536a54;font-size:11px;cursor:pointer;text-decoration:none}.event-info{padding:18px 0;border-bottom:1px solid #e6e6df}.event-info p{font-size:13px;color:#6f766b;line-height:1.6;margin:4px 0}.agenda-head{display:flex;align-items:center;justify-content:space-between;margin:25px 0 15px}.agenda-head h3{font:500 25px var(--font-display);margin:5px 0}.agenda-empty{background:#f3f3ed;padding:16px;border-radius:10px;color:#777d72;font-size:12px}.agenda-item{display:grid;grid-template-columns:55px 1fr 32px 32px;gap:8px;align-items:center;border-bottom:1px solid #eee;padding:13px 0}.agenda-item time{font-size:13px;font-weight:700;color:#536a54}.agenda-item div{display:flex;flex-direction:column;gap:4px}.agenda-item strong{font-size:13px}.agenda-item small{font-size:11px;color:#82877e}.event-detail__footer{display:flex;justify-content:flex-end;gap:8px;border-top:1px solid #e6e6df;margin-top:22px;padding-top:16px}.sheet-backdrop--nested{z-index:110;background:#2228}.guest-sheet--small{max-width:480px}.guest-sheet form label{display:flex;flex-direction:column;gap:7px}.guest-sheet form footer{display:flex;justify-content:flex-end;gap:8px;margin-top:8px}@media(max-width:760px){.events-page{padding:25px 17px 50px}.events-head{align-items:flex-start;flex-direction:column}.event-next{padding:20px}.event-grid{grid-template-columns:1fr}.event-card__title{font-size:24px}.agenda-head{align-items:flex-start;gap:8px}.agenda-head .button{font-size:10px;padding:9px}.agenda-item{grid-template-columns:45px 1fr 30px 30px}}
</style>
